const faqs = () => `<div class="resource-page faq-page">${resourceNav('faq')}<section class="resource-hero faq-hero"><div class="resource-hero-copy"><span class="resource-kicker">ANSWERS / PATIENT RESOURCES</span><h1>Let’s make it clearer.</h1><p>Quick answers about visits, coverage, and getting here. Search a question or choose a topic below.</p><label class="resource-search faq-search"><span class="search-symbol" aria-hidden="true">⌕</span><span class="sr-only">Search frequently asked questions</span><input id="faqSearch" type="search" placeholder="Search appointments, insurance, portal…" autocomplete="off"></label></div><div class="faq-hero-mark" aria-hidden="true">?</div></section><section class="resource-section"><div class="faq-layout"><aside><span class="resource-kicker">FIND AN ANSWER</span><h2>Browse by topic.</h2><div class="faq-categories" role="group" aria-label="FAQ topics"><button class="active" data-faq-category="all" aria-pressed="true">All questions</button>${faqGroups.map(([id,name])=>`<button data-faq-category="${id}" aria-pressed="false">${name}</button>`).join('')}</div><p>For personal coverage or clinical questions, the team can help directly.</p><a href="tel:+12148726502">Call or text the office</a></aside><div class="faq-results"><div class="faq-result-head"><span id="faqCount" aria-live="polite">12 questions</span><span>Tap a question to expand</span></div>${faqGroups.map(([id,name,items])=>`<div class="faq-group" data-faq-group="${id}"><h3>${name}</h3>${items.map(([q,a],i)=>`<details data-faq-item="${(q+' '+a).toLowerCase().replace(/"/g,'&quot;')}"><summary><span>${q}</span><i aria-hidden="true"></i></summary><p>${a}</p></details>`).join('')}</div>`).join('')}<p id="faqEmpty" class="faq-empty" hidden>No matching questions. Try another word or call the team at <a href="tel:+12148726502">(214) 872-6502</a>.</p></div></div></section><section class="resource-section resource-tint"><div class="faq-closing"><span class="resource-kicker">STILL CURIOUS?</span><h2>Ask a person who can help.</h2><p>The Articella team can confirm current scheduling, coverage, and next steps for your situation.</p><a class="button button-dark" href="tel:+12148726502">Call or text (214) 872-6502</a></div></section></div>`;
const renderers = {'':home,about,providers:providersPage,services:servicesPage,service:ServiceExperience.render,memberships,'new-patients':newPatients,insurance,insights,faq:faqs,locations,contact,portal,privacy,terms};
function render(){const p=path();app.innerHTML=renderers[p]();document.title=p==='service'?(ServiceExperience.title()+' | Articella · Frisco, TX'):(p?({'new-patients':'New Patients','services':'Primary Care Services','insights':'Insights & Events','faq':'Patient FAQs','insurance':'Insurance & Billing'}[p]||p[0].toUpperCase()+p.slice(1))+' | ':'')+'Articella · Frisco, TX';const meta=document.querySelector('meta[name=description]');if(meta)meta.content=({'':'Personalized primary care in Frisco, Texas. Meet the Articella team, explore care options and plan your visit.','about':'Learn about Articella’s mission, founding story and approach to primary care in Frisco, TX.','providers':'Meet Articella’s care team and explore physician-led primary care in Frisco, TX.','services':'Explore preventive care, sick visits, chronic care and coordination at Articella in Frisco, TX.','service':ServiceExperience.description(),'memberships':'Compare Articella individual, couple, family, student, visitor and single-visit care options.','new-patients':'Prepare for your first visit to Articella in Frisco, TX.','insurance':'Explore insurance, self-pay and billing guidance for Articella primary care.','insights':'Explore Articella articles, clinician videos and practice updates.','faq':'Find answers about appointments, coverage, visits and Articella care.','locations':'Find Articella in Frisco, TX, with clinic hours and directions.','contact':'Contact Articella primary care in Frisco, TX to ask a question or plan a visit.'}[p]||'Articella primary care in Frisco, Texas.');document.querySelectorAll('.nav>a').forEach(a=>{const active=a.getAttribute('href')==='#/'+p;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.getElementById('nav').classList.remove('open');document.querySelectorAll('.nav-group').forEach(group=>{group.classList.remove('open');group.querySelector('button')?.setAttribute('aria-expanded','false')});document.querySelector('.services-group').classList.toggle('active',p==='service'||p==='services');document.querySelector('.resources-group').classList.toggle('active',['new-patients','insurance','insights','locations','faq'].includes(p));document.getElementById('menuToggle').setAttribute('aria-expanded','false');if(p==='memberships'&&document.getElementById('planContent')){document.getElementById('planContent').innerHTML=membershipPanels()}window.scrollTo({top:0,behavior:'instant'})}
window.addEventListener('hashchange',render);render();
const storyChapters = [
  {kicker:'THE STARTING POINT',title:'Notice the disconnect.',body:'Too many visits felt rushed, leaving little space to understand the person or plan ahead.',image:'about-conversation.webp',alt:'Physician listening to a patient in a care conversation'},
  {kicker:'THE SHIFT',title:'Make prevention central.',body:'Give long-term health a place in the conversation alongside today’s immediate concern.',image:'about-prevention.webp',alt:'Physician and patient discussing a preventive wellness plan'},
  {kicker:'THE PLACE',title:'Build the practice in Frisco.',body:'Bring the idea into a local setting designed for ongoing primary care relationships.',image:'care-interior.webp',alt:'Warm and welcoming clinic interior'},
  {kicker:'THE CONTINUATION',title:'Keep learning together.',body:'Let the care team’s conversations and clinical judgment guide each patient’s next step.',image:'about-team-work.webp',alt:'Care team reviewing a patient care plan'}
];
document.addEventListener('click',e=>{const jump=e.target.closest('[data-scroll-target]');if(jump){document.getElementById(jump.dataset.scrollTarget)?.scrollIntoView({behavior:'smooth'});return}const chapter=e.target.closest('[data-story-tab]');if(chapter){const i=Number(chapter.dataset.storyTab),c=storyChapters[i],stage=document.getElementById('storyChapterStage');document.querySelectorAll('[data-story-tab]').forEach(t=>{t.classList.toggle('active',t===chapter);t.setAttribute('aria-selected',String(t===chapter))});stage.classList.remove('chapter-enter');void stage.offsetWidth;stage.innerHTML=`<div class="story-chapter-visual"><img src="assets/${c.image}" alt="${c.alt}" loading="eager"></div><div class="story-chapter-content"><span>${c.kicker}</span><h3>${c.title}</h3><p>${c.body}</p></div>`;stage.classList.add('chapter-enter');return}const teamProfile=e.target.closest('[data-team-profile]');if(teamProfile){const p=teamProfiles[Number(teamProfile.dataset.teamProfile)];document.getElementById('profileBody').innerHTML=`<div class="profile-image"><img src="assets/${p.image}" alt="${p.name}"></div><div class="profile-copy"><div class="eyebrow">MEET THE ARTICELLA TEAM</div><h2>${p.name}</h2><strong>${p.intro}</strong><p>${p.body}</p><div class="profile-focus">${p.focus}</div><p class="subtle">Profile summarized from the current Articella team page for design review. Confirm role, biography and appointment eligibility before launch.</p><a class="button button-dark" href="#/contact" onclick="document.getElementById('profileDialog').close()">Contact the team</a></div>`;document.getElementById('profileDialog').showModal();return}const profile=e.target.closest('[data-profile]');if(profile){const i=Number(profile.dataset.profile),p=providers[i],d=profileDetails[i];document.getElementById('profileBody').innerHTML=`<div class="profile-image"><img src="${['assets/rahul.jpg','assets/sylaza.jpg','assets/anupa.webp'][i]}" alt="${p.name}"></div><div class="profile-copy"><div class="eyebrow">MEET THE CARE TEAM</div><h2>${p.name}</h2><strong>${d.intro}</strong><p>${d.body}</p><div class="profile-focus">${d.focus}</div><p class="subtle">Biography summarized from Articella’s current site for presentation. Confirm credentials, scope and scheduling before launch.</p><button class="button button-dark book-trigger">Ask about booking </button></div>`;document.getElementById('profileDialog').showModal();return}const bookBtn=e.target.closest('.book-trigger');if(bookBtn){const profileDialog=document.getElementById('profileDialog');if(profileDialog.open)profileDialog.close();bookingDialog.showModal();return}if(e.target.closest('[data-close-dialog]'))bookingDialog.close();const tab=e.target.closest('[data-plan-tab]');if(tab){document.querySelectorAll('[data-plan-tab]').forEach(t=>{t.classList.toggle('active',t===tab);t.setAttribute('aria-selected',String(t===tab))});document.getElementById('planContent').innerHTML=membershipPanels(tab.dataset.planTab)}const filter=e.target.closest('[data-filter]');if(filter){document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===filter);b.setAttribute('aria-pressed',String(b===filter))});document.querySelectorAll('#resourceGrid>[data-type]').forEach(c=>c.hidden=filter.dataset.filter!=='all'&&c.dataset.type!==filter.dataset.filter)}const team=e.target.closest('[data-team-scroll]');if(team){document.getElementById('teamTrack').scrollBy({left:team.dataset.teamScroll==='next'?350:-350,behavior:'smooth'})}if(e.target.closest('[data-newsletter]'))document.getElementById('newsletterStatus').innerHTML='<p class="status">Newsletter sign-up is a concept. No email address is requested or stored.</p>';const chat=e.target.closest('[data-chat]');if(chat)respondToGuide(chat.dataset.chat)});
document.getElementById('profileClose').onclick=()=>document.getElementById('profileDialog').close();document.getElementById('bookingClose').onclick=()=>bookingDialog.close();document.getElementById('menuToggle').onclick=()=>{const nav=document.getElementById('nav');const open=nav.classList.toggle('open');document.getElementById('menuToggle').setAttribute('aria-expanded',String(open))};const navGroups=[...document.querySelectorAll('.nav-group')];function closeMenus(except){navGroups.forEach(group=>{if(group===except)return;group.classList.remove('open');group.querySelector('button')?.setAttribute('aria-expanded','false')})}navGroups.forEach(group=>{const button=group.querySelector('button');button.onclick=()=>{const open=!group.classList.contains('open');closeMenus(group);group.classList.toggle('open',open);button.setAttribute('aria-expanded',String(open))};group.addEventListener('focusout',e=>{if(!group.contains(e.relatedTarget))closeMenus()})});document.addEventListener('pointerdown',e=>{if(!navGroups.some(group=>group.contains(e.target)))closeMenus()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){const open=navGroups.find(group=>group.classList.contains('open'));if(open){const button=open.querySelector('button');closeMenus();button.focus()}}});const chatPanel=document.getElementById('chatPanel'),chatToggle=document.getElementById('chatToggle'),chatBody=document.getElementById('chatBody'),chatMessages=document.getElementById('chatMessages');
function setGuideOpen(open){chatPanel.hidden=!open;chatToggle.setAttribute('aria-expanded',String(open));chatToggle.setAttribute('aria-label',open?'Close Articella care guide':'Open Articella care guide');if(open)document.getElementById('chatInput').focus();else chatToggle.focus()}
const guideTopics={
  services:{text:'Articella lists preventive care, annual physicals, sick visits, chronic condition management, telehealth, and follow-up coordination. Explore the visit categories to find a starting point.',label:'Explore primary care',href:'#/services'},
  plans:{text:'You can compare individual, couple, and family memberships, student and visitor packages, or one-time visits. The published options have different inclusions; confirm current prices and written terms with the practice.',label:'Compare care options',href:'#/memberships'},
  insurance:{text:'Articella lists several insurers, but participation depends on your exact plan, network, provider, and visit. Check with both the practice and your insurer before scheduling.',label:'Insurance & billing',href:'#/insurance'},
  booking:{text:'You can explore the current booking destination or call or text the Frisco team. The practice can help confirm the right visit type and availability.',label:'Contact the team',href:'#/contact'},
  hours:{text:'Articella’s public listing shows Monday–Friday 8:30 AM–4:30 PM and Saturday 8:30 AM–12:00 PM at 10234 Coit Rd, Suite 100, Frisco. Please confirm hours before visiting.',label:'Directions & hours',href:'#/locations'},
  providers:{text:'Meet Dr. Rahul Singh, Dr. Sylaza Kantamneni, and Anupa Adhikari on the care team page. The practice can confirm current schedules and appointment eligibility.',label:'Meet the care team',href:'#/providers'},
  newpatients:{text:'Before a first visit, confirm your appointment, coverage, and any forms the practice requests. The new patient guide brings those steps together.',label:'New patient guide',href:'#/new-patients'},
  portal:{text:'The secure patient portal is a separate clinical system. Use the portal link on this site, or contact the practice if you need access help.',label:'Patient portal',href:'#/portal'},
  urgent:{text:'This guide cannot assess symptoms or provide medical advice. For an emergency, call 911. For a non-emergency question about an appointment, contact the practice directly.',label:'Contact the practice',href:'#/contact'},
  fallback:{text:'I can help you find Articella’s services, memberships, insurance guidance, providers, office hours, booking, and patient resources. Try asking about one of those topics, or reach the team directly.',label:'Contact the team',href:'#/contact'}
};
function guideTopicFor(question){const q=question.toLowerCase();if(/emergency|chest pain|stroke|suicid|severe|bleeding|911/.test(q))return 'urgent';if(/insurance|coverage|accept|aetna|cigna|medicare|billing|copay/.test(q))return 'insurance';if(/member|concierge|plan|price|cost|fee|student|visitor|single visit/.test(q))return 'plans';if(/doctor|provider|physician|clinician|team|rahul|sylaza|anupa/.test(q))return 'providers';if(/hour|open|address|where|location|direction|frisco|saturday/.test(q))return 'hours';if(/book|schedule|appointment|call|contact/.test(q))return 'booking';if(/new patient|first visit|forms|prepare/.test(q))return 'newpatients';if(/portal|record|login/.test(q))return 'portal';if(/service|care|sick|physical|prevent|screen|telehealth|chronic/.test(q))return 'services';return 'fallback'}
function respondToGuide(topic,question=''){const answer=guideTopics[topic]||guideTopics.fallback;const exchange=document.createElement('div');exchange.className='chat-exchange';if(question){const user=document.createElement('p');user.className='chat-user-bubble';user.textContent=question;exchange.append(user)}const reply=document.createElement('div');reply.className='chat-answer';const avatar=document.createElement('span');avatar.className='chat-message-avatar';avatar.setAttribute('aria-hidden','true');avatar.textContent='✦';const bubble=document.createElement('div');bubble.className='chat-bubble';const label=document.createElement('small');label.textContent='ARTICELLA GUIDE';const message=document.createElement('p');message.textContent=answer.text;const action=document.createElement('a');action.href=answer.href;action.className='chat-answer-action';action.textContent=answer.label+'  →';bubble.append(label,message,action);reply.append(avatar,bubble);exchange.append(reply);chatMessages.append(exchange);chatBody.scrollTop=chatBody.scrollHeight}
chatToggle.onclick=()=>setGuideOpen(chatPanel.hidden);document.getElementById('chatClose').onclick=()=>setGuideOpen(false);document.getElementById('chatReset').onclick=()=>{chatMessages.replaceChildren();chatBody.scrollTop=0;document.getElementById('chatInput').focus()};document.getElementById('chatForm').onsubmit=e=>{e.preventDefault();const input=document.getElementById('chatInput'),question=input.value.trim();if(!question)return;respondToGuide(guideTopicFor(question),question);input.value='';input.focus()};chatPanel.addEventListener('click',e=>{if(e.target.closest('.chat-answer-action'))setGuideOpen(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!chatPanel.hidden)setGuideOpen(false)});
document.addEventListener('submit',e=>{if(e.target.id==='contactForm'){e.preventDefault();document.getElementById('formStatus').innerHTML='<div class="status">Confirmation preview. Your message was not sent or stored. The approved production CRM will handle enquiries.</div>';e.target.reset()}});

// Patient resource controls are local UI only; no personal information is transmitted.
document.addEventListener('input',e=>{if(e.target.id==='planSearch'){const term=e.target.value.trim().toLowerCase();let count=0;document.querySelectorAll('[data-plan-name]').forEach(row=>{row.hidden=!row.dataset.planName.includes(term);if(!row.hidden)count++});const empty=document.getElementById('planEmpty');if(empty)empty.hidden=count>0;const selected=document.querySelector('[data-plan-index][aria-pressed=true]');if(selected?.hidden){const first=document.querySelector('[data-plan-index]:not([hidden])');if(first)selectPlan(first)}}if(e.target.id==='faqSearch')filterFAQs()});
document.addEventListener('change',e=>{if(e.target.matches('[data-prep]')){const all=[...document.querySelectorAll('[data-prep]')],count=all.filter(input=>input.checked).length;document.getElementById('prepProgress').textContent=`${count} of ${all.length} ready`;document.getElementById('prepBar').style.width=`${count/all.length*100}%`}});
document.addEventListener('click',e=>{const category=e.target.closest('[data-faq-category]');if(category){document.querySelectorAll('[data-faq-category]').forEach(button=>{button.classList.toggle('active',button===category);button.setAttribute('aria-pressed',String(button===category))});filterFAQs()}});
function filterFAQs(){const query=(document.getElementById('faqSearch')?.value||'').trim().toLowerCase(), category=document.querySelector('[data-faq-category].active')?.dataset.faqCategory||'all';let total=0;document.querySelectorAll('[data-faq-group]').forEach(group=>{let visible=0;group.querySelectorAll('[data-faq-item]').forEach(item=>{const match=(category==='all'||group.dataset.faqGroup===category)&&item.dataset.faqItem.includes(query);item.hidden=!match;if(match)visible++});group.hidden=!visible;total+=visible});const count=document.getElementById('faqCount');if(count)count.textContent=`${total} ${total===1?'question':'questions'}`;const empty=document.getElementById('faqEmpty');if(empty)empty.hidden=total>0}

function selectPlan(tile){const plan=listedPlans[Number(tile.dataset.planIndex)];document.querySelectorAll('[data-plan-index]').forEach(item=>item.setAttribute('aria-pressed',String(item===tile)));document.getElementById('planDetailTitle').textContent=plan.name;document.getElementById('planDetailText').textContent=plan.note;document.getElementById('planDetailCompany').textContent=plan.company;document.getElementById('planDetailLink').href=plan.website;const panel=document.getElementById('planDetail');panel.classList.remove('detail-refresh');void panel.offsetWidth;panel.classList.add('detail-refresh')}
document.addEventListener('click',e=>{const tile=e.target.closest('[data-plan-index]');if(tile)selectPlan(tile)});
